// ?applyIndicatorColour@Rva001C15F0Owner@@QAEXXZ
// partial score=0.93 date=2026-09-21
// ?applyIndicatorColour@Rva001C15F0Owner@@QAEXXZ  rva=0x001C15F0 size=132
// partial score=0.93 -- 9 non-relocation bytes left, all one shape.
//
// Identity is NOT proven: no matched caller names a symbol, there is no vtable
// slot and no string literal, so the row keeps its address token. What the body
// DOES prove: it reads TheWritableGlobalData->+0x218, two of its own fields at
// +0x244 and +0x23c, calls the pinned Team::getControllingPlayer through the
// ILT thunk at 0x0002369B and passes a Player field (+0x1c8 or +0x1c4) to the
// pinned Drawable::setIndicatorColor at 0x00028C09.
//
// LEVER THAT MOVED IT (new, 2026-09-21): the two player-colour arms do NOT call
// and return -- they ASSIGN the shared colour local and fall into ONE call at
// the end. VC7.1 then tail-duplicates the 11-byte `mov ecx,<r>` / `push` /
// `call` / `pop` / `pop` / `ret` block into all three arms rather than jumping
// to it, which is where retail's three copies come from, and the colour local
// lands in EAX so the arm loads read `mov eax,[eax+0x1c8]` exactly like retail.
// That killed the register half of the residue every earlier verdict blamed on
// "regalloc" (14 of them: the call-and-return spelling forces EDX in the
// mode==4 arm).
//
// RESIDUE (9 bytes = 3 sites x 3): retail emits `mov ecx,edi` BEFORE `push eax`
// at each duplicated tail; we emit `push eax` then `mov ecx,edi`.
// Measured rule (listing harness, /FAsc): VC7.1 puts the receiver first only
// when the receiver is a LOAD -- `mov ecx,DWORD PTR [esi+4]` for a member
// receiver, `mov ecx,_r$[esp-4]` for a stack one -- and sinks it after the push
// whenever the receiver is already a register copy. Across every matched body
// in the image the same split holds: 940 order-A sites against 3 order-B, and
// all three order-B sites load the receiver or the argument from memory in
// place (0x002980A0, 0x005B1610, 0x000DF5A0).
// Tried and rejected, all still order A: /G5 /G6 /G7 /Ob0 /Ob1 /Ot /Oy- /Gy
// /GF /Oi- /Ox; deref, reference receiver, qualified call, const receiver copy,
// int colour, one-field struct colour, declaration-order swap, own-block call,
// extra statement before the call, inline accessor for the field, an inline
// helper taking (receiver, colour), the whole tree as a ternary argument, the
// tree hoisted into an inline colour accessor, goto/do-while/switch arms, a
// seeded colour local, and writing the colour through a pointer local.
// NEXT LEVER: the receiver has to reach the call as a memory READ that register
// allocation later folds into EDI -- i.e. a source shape where the pointer is
// re-read at the call site, not a local holding the virtual call's result.
class BfmeInfoCA
{
public:
	unsigned char m_bfmeHeadCA[0x1c4];
	unsigned int m_bfmePlainCA;
	unsigned int m_bfmeAltCA;
};

class BfmeOwnerCA
{
public:
	BfmeInfoCA *bfmeInfoCA();
};

class BfmeResCA
{
public:
	void bfmeApplyCA(unsigned int colour);
};

struct Rva006C9270GlobalData
{
	unsigned char m_bfmeHeadCA[0x218];
	int m_bfmeModeCA;
};

extern Rva006C9270GlobalData *TheWritableGlobalData;

class Rva001C15F0Owner
{
public:
	virtual void bfmeSlot00CA();
	virtual void bfmeSlot01CA();
	virtual void bfmeSlot02CA();
	virtual void bfmeSlot03CA();
	virtual void bfmeSlot04CA();
	virtual void bfmeSlot05CA();
	virtual void bfmeSlot06CA();
	virtual void bfmeSlot07CA();
	virtual void bfmeSlot08CA();
	virtual void bfmeSlot09CA();
	virtual BfmeResCA *bfmeGetCA();

	void applyIndicatorColour();

	unsigned char m_bfmeHeadCA[0x238];
	BfmeOwnerCA *m_bfmeOwnerCA;
	unsigned char m_bfmePadCA[4];
	unsigned int m_bfmeColourCA;
};

void Rva001C15F0Owner::applyIndicatorColour()
{
	BfmeResCA *r = bfmeGetCA();

	if (r == 0)
		return;

	unsigned int colour;
	BfmeInfoCA *info;

	if (TheWritableGlobalData->m_bfmeModeCA == 4)
	{
		if (m_bfmeColourCA != 0)
			colour = m_bfmeColourCA;
		else if (m_bfmeOwnerCA != 0 && (info = m_bfmeOwnerCA->bfmeInfoCA()) != 0)
			colour = info->m_bfmeAltCA;
		else
			colour = 0xff000000;
	}
	else
	{
		if (m_bfmeColourCA != 0)
			colour = m_bfmeColourCA;
		else if (m_bfmeOwnerCA != 0 && (info = m_bfmeOwnerCA->bfmeInfoCA()) != 0)
			colour = info->m_bfmePlainCA;
		else
			colour = 0xff000000;
	}

	r->bfmeApplyCA(colour);
}
